import lombok.Getter;
import lombok.NoArgsConstructor;
import lombok.Setter;

import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.List;

@Entity
@Table(name = "drama")
@Getter
@Setter
@NoArgsConstructor
public class Drama {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
