import axios from 'axios'

const client = axios.create({ baseURL: '' })

client.interceptors.request.use((config) => {
  const token = localStorage.getItem('token')
  if (token) config.headers.Authorization = `Bearer ${token}`
  return config
})

client.interceptors.response.use(
  (res) => res,
  (error) => {
    if (error.response?.status === 401) {
      localStorage.removeItem('token')
      // avoid redirect loop on login page itself
      if (!window.location.pathname.startsWith('/login')) {
        window.location.href = `/login?from=${encodeURIComponent(window.location.pathname + window.location.search)}`
      }
    }
    return Promise.reject(error)
  },
)
export default client
```

Note: hard navigation (window.location) loses SPA state but is simple and reliable. The plan explicitly says "响应拦截器遇 401 清 token + 跳 /login?from=<当前路径>".

