// hooks/useDramaInteractions.ts
import { useCallback, useEffect, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { useAuth } from '../store/AuthContext'

/** 阶段2：点赞/收藏仅 UI + 未登录引导；写库在里程碑 4。 */
export function useDramaInteractions(dramaId: number | string | undefined) {
  const { user } = useAuth()
  const navigate = useNavigate()
  const [hint, setHint] = useState('')

  useEffect(() => {
    if (!hint) return
    const timer = setTimeout(() => setHint(''), 2500)
    return () => clearTimeout(timer)
  }, [hint])

  const guarded = useCallback(
    (message: string) => {
      if (!user) {
        const from = encodeURIComponent(typeof dramaId === 'number' ? `/drama/${dramaId}` : window.location.pathname)
        navigate(`/login?from=${from}`)
        return
      }
      setHint(message)
    },
    [user, dramaId, navigate],
  )

  const like = useCallback(() => guarded('点赞功能即将上线，敬请期待'), [guarded])
  const favorite = useCallback(() => guarded('收藏功能即将上线，敬请期待'), [guarded])

  return { like, favorite, hint }
}
