  const [reloadKey, setReloadKey] = useState(0)

  useEffect(() => {
    let cancelled = false
    setState('loading')
    listDramas()
      .then((data) => {
        if (cancelled) return
        setDramas(data)
        setState('ready')
      })
      .catch((err) => {
        if (cancelled) return
        setError(getApiErrorMessage(err))
        setState('error')
      })
    return () => {
      cancelled = true
    }
  }, [reloadKey])

  // 分类条随种子数据生成（全部 + 去重分类），数据量小走前端过滤
  const categories = useMemo(
    () => ['全部', ...Array.from(new Set(dramas.map((drama) => drama.category)))],
    [dramas],
  )
