    const v = document.querySelector("video");
    return {
      boxRatio: rect ? (rect.width / rect.height).toFixed(3) : null,
      videoPixelRatio: v && v.videoWidth ? (v.videoWidth / v.videoHeight).toFixed(3) : null,
      boxWidth: rect ? Math.round(rect.width) : null,
      hasHorizontalScroll: document.documentElement.scrollWidth > document.documentElement.clientWidth,
    };
  });
  results.push({ width, ...data });
}
